import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BGlkWkwp.js";const u=JSON.parse('{"title":"Disclosure","description":"","frontmatter":{},"headers":[],"relativePath":"components/disclosure.md","filePath":"components/disclosure.md"}'),s={name:"components/disclosure.md"};function d(i,e,n,h,l,c){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="disclosure" tabindex="-1">Disclosure <a class="header-anchor" href="#disclosure" aria-label="Permalink to &quot;Disclosure&quot;">​</a></h1><p>Disclosure is a group that opens and closes, with its current value in its head.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it for settings that are not needed often, so that a panel stays short. Stack several with gap 0: a line divides them. The <code>value</code> shows what the group is set to while it is closed. A group that is always open is a <a href="./section">Section</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>required</td><td>The name of the group</td></tr><tr><td><code>value</code></td><td></td><td>The current value, on the right of the head</td></tr><tr><td><code>open</code></td><td><code>false</code></td><td>The content shows (bindable)</td></tr><tr><td><code>ontoggle</code></td><td></td><td>Called with the new state when the head is pressed</td></tr><tr><td><code>children</code></td><td>required</td><td>The content</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The head is a button as tall as a list item, with pad-md at the sides, on the raise surface (raise-2 on hover), with a chevron on the left, the title, and the value muted at the right end; the head has <code>aria-expanded</code> and controls the content. Open, the content is a container with pad-md, its children gap-sm apart; controls inside have a button&#39;s height. Disclosures next to each other touch, with a line between them.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/disclosure/" title="Disclosure" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/disclosure/" target="_blank" rel="noopener">Disclosure</a></figcaption></figure>',10)])])}const m=t(s,[["render",d]]);export{u as __pageData,m as default};
